package main

import "sync"

// Correct fan-in: forwarders only send + Done; ONE watcher closes.
func merge(cs ...<-chan int) <-chan int {
	out := make(chan int)
	var wg sync.WaitGroup
	wg.Add(len(cs))
	for _, c := range cs {
		go func(c <-chan int) {
			defer wg.Done()
			for v := range c {
				out <- v // forwarder NEVER closes out
			}
		}(c)
	}
	go func() { wg.Wait(); close(out) }() // the single closer
	return out
}
