package main

import "fmt"

func main() {
	a := make(chan int, 2)
	b := make(chan int, 2)
	a <- 1; a <- 2; close(a)
	b <- 3; close(b)

	var got []int
	for a != nil || b != nil { // loop until both are disabled
		select {
		case v, ok := <-a:
			if !ok { a = nil; continue } // nil disables this case (no busy-loop)
			got = append(got, v)
		case v, ok := <-b:
			if !ok { b = nil; continue }
			got = append(got, v)
		}
	}
	fmt.Println(len(got)) // Output: 3
}

package main

import (
	"fmt"
	"sync"
)

type item struct {
	idx int
	val int
}

func main() {
	inputs := []int{10, 20, 30, 40}
	out := make([]int, len(inputs))
	jobs := make(chan item)
	var wg sync.WaitGroup
	for w := 0; w < 3; w++ { // fan out — order of completion is nondeterministic
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := range jobs {
				out[j.idx] = j.val * 2 // distinct index -> reassembled in order, no race
			}
		}()
	}
	for i, v := range inputs {
		jobs <- item{i, v}
	}
	close(jobs)
	wg.Wait()
	fmt.Println(out) // Output: [20 40 60 80]
}

