import (
	"fmt"
	"sync"
)

func gen(nums ...int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out) // sender owns and closes its channel
		for _, n := range nums {
			out <- n
		}
	}()
	return out
}

func square(in <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for n := range in { // fan-out: many of these share one `in`
			out <- n * n
		}
	}()
	return out
}

func merge(cs ...<-chan int) <-chan int {
	out := make(chan int)
	var wg sync.WaitGroup
	wg.Add(len(cs))
	for _, c := range cs {
		go func(c <-chan int) { // forward one source into out
			defer wg.Done()
			for v := range c {
				out <- v
			}
		}(c)
	}
	go func() { wg.Wait(); close(out) }() // single closer, after all done
	return out
}

func main() {
	in := gen(1, 2, 3, 4, 5)
	// fan-out: three workers all read `in`
	c1, c2, c3 := square(in), square(in), square(in)
	sum := 0
	for v := range merge(c1, c2, c3) { // fan-in
		sum += v
	}
	fmt.Println(sum) // 1+4+9+16+25 = 55
}

