package solution

import (
	"sort"
	"testing"
)

func emit(vals ...int) <-chan int {
	c := make(chan int)
	go func() {
		defer close(c)
		for _, v := range vals {
			c <- v
		}
	}()
	return c
}

func TestMerge(t *testing.T) {
	merged := Merge(emit(1, 2), emit(3), emit(4, 5, 6))
	var got []int
	for v := range merged { // must terminate => Merge must close out
		got = append(got, v)
	}
	sort.Ints(got) // order is nondeterministic; compare as a multiset
	want := []int{1, 2, 3, 4, 5, 6}
	if len(got) != len(want) {
		t.Fatalf("got %v want %v", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Errorf("index %d: got %d want %d", i, got[i], want[i])
		}
	}
}

