func merge(cs ...<-chan int) <-chan int {
	out := make(chan int)
	var wg sync.WaitGroup
	wg.Add(len(cs)) // count forwarders BEFORE launching them
	for _, c := range cs {
		go func(c <-chan int) {
			defer wg.Done()
			for v := range c { out <- v }
		}(c)
	}
	go func() { wg.Wait(); close(out) }() // now waits for every forwarder
	return out
}

func FanOutFanIn(in <-chan int, workers int, f func(int) int) <-chan int {
	if workers < 1 {
		workers = 1
	}
	out := make(chan int)
	var wg sync.WaitGroup
	wg.Add(workers)
	for w := 0; w < workers; w++ {
		go func() {
			defer wg.Done()
			for v := range in { // fan-out: all workers share `in`
				out <- f(v)     // fan-in: all send into one `out`
			}
		}()
	}
	go func() { wg.Wait(); close(out) }() // single closer after all done
	return out
}

func MergeCancel(done <-chan struct{}, cs ...<-chan int) <-chan int {
	out := make(chan int)
	var wg sync.WaitGroup
	wg.Add(len(cs))
	forward := func(c <-chan int) {
		defer wg.Done()
		for v := range c { // ends when c is closed & drained
			select {
			case out <- v: // normal forward
			case <-done: // cancelled -> stop this forwarder
				return
			}
		}
	}
	for _, c := range cs {
		go forward(c)
	}
	go func() { wg.Wait(); close(out) }() // single closer, after all forwarders exit
	return out
}

